def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_order_history_unknown_customer_is_404(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_order_history_with_no_orders(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_order_history_is_newest_first_and_only_for_that_customer(shop):
    first = order(shop, "c1", ("PEN", 1)).body["order_id"]
    order(shop, "c2", ("PEN", 1))
    second = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert [o["order_id"] for o in response.body["orders"]] == [second, first]


def test_order_history_totals_match_order_summary_including_discount(shop):
    # BOOK x 4 = 10_000 cents, which qualifies for the 10% standard discount.
    discounted = order(shop, "c1", ("BOOK", 4)).body["order_id"]
    # Gold customer c2 gets 15% off the same subtotal.
    gold = order(shop, "c2", ("BOOK", 4)).body["order_id"]

    standard_entry = shop.insights.handle_order_history("c1").body["orders"][0]
    gold_entry = shop.insights.handle_order_history("c2").body["orders"][0]

    assert standard_entry == {"order_id": discounted, "status": "placed", "total_cents": 9_000}
    assert gold_entry == {"order_id": gold, "status": "placed", "total_cents": 8_500}
    assert shop.orders.handle_get(discounted).body["total_cents"] == standard_entry["total_cents"]
    assert shop.orders.handle_get(gold).body["total_cents"] == gold_entry["total_cents"]


def test_order_history_includes_cancelled_orders_with_status(shop):
    kept = order(shop, "c1", ("PEN", 1)).body["order_id"]
    cancelled = order(shop, "c1", ("PEN", 2)).body["order_id"]
    shop.orders.handle_cancel(cancelled)
    response = shop.insights.handle_order_history("c1")
    assert response.body["orders"] == [
        {"order_id": cancelled, "status": "cancelled", "total_cents": 600},
        {"order_id": kept, "status": "placed", "total_cents": 300},
    ]

