from __future__ import annotations

from typing import Any

from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int
from orders.domain.orders import Order
from orders.infrastructure.customers import InMemoryCustomerRepository


class CustomerInsightsController:
    def __init__(self, orders: OrderService, customers: InMemoryCustomerRepository) -> None:
        self._orders = orders
        self._customers = customers

    def _lifetime_value(self, orders: list[Order]) -> tuple[int, int]:
        """(order_count, lifetime_value_cents) over the orders that are not cancelled."""
        active = [order for order in orders if order.status != "cancelled"]
        return len(active), sum(self._orders.summarize(order).total_cents for order in active)

    def handle_order_history(self, customer_id: str) -> Response:
        """A customer's orders, newest first, with totals as reported by the order summary."""
        try:
            orders = self._orders.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        # list_for_customer returns creation order; newest first is the reverse.
        entries: list[dict[str, Any]] = []
        for order in reversed(orders):
            summary = self._orders.summarize(order)
            entries.append({"order_id": order.order_id, "status": order.status,
                            "total_cents": summary.total_cents})
        return Response(200, {"customer_id": customer_id, "orders": entries})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Non-cancelled order count and the sum of their totals, as in the order history."""
        try:
            orders = self._orders.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        order_count, lifetime_value_cents = self._lifetime_value(orders)
        return Response(200, {"customer_id": customer_id, "order_count": order_count,
                              "lifetime_value_cents": lifetime_value_cents})

    def handle_top_customers(self, limit: Any) -> Response:
        """Customers ranked by lifetime value (highest first, then customer_id), excluding zero."""
        try:
            limit = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)
        ranked = []
        for customer in self._customers.list_all():
            _, value = self._lifetime_value(self._orders.list_for_customer(customer.customer_id))
            if value > 0:
                ranked.append((value, customer))
        ranked.sort(key=lambda pair: (-pair[0], pair[1].customer_id))
        return Response(200, {"customers": [
            {"customer_id": customer.customer_id, "name": customer.name, "lifetime_value_cents": value}
            for value, customer in ranked[:limit]]})

